import{_ as t,o as a,c as r,ae as i}from"./chunks/framework.RRduUuAx.js";const d=JSON.parse('{"title":"ADR-001: TypeScript + Bun as Primary Language for heliosApp","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/ADR-001-typescript-over-go.md","filePath":"adrs/ADR-001-typescript-over-go.md"}'),o={name:"adrs/ADR-001-typescript-over-go.md"};function n(s,e,p,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-001-typescript-bun-as-primary-language-for-heliosapp" tabindex="-1">ADR-001: TypeScript + Bun as Primary Language for heliosApp <a class="header-anchor" href="#adr-001-typescript-bun-as-primary-language-for-heliosapp" aria-label="Permalink to &quot;ADR-001: TypeScript + Bun as Primary Language for heliosApp&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Proposed (requires 3 approvals per constitution L116-118)</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The heliosApp constitution (<code>docs/reference/constitution.md</code>) states: &quot;Prefer Go where feasible for core systems.&quot; This ADR documents a permanent exception to that rule for the heliosApp repository.</p><p>heliosApp is a desktop control-plane application built on <strong>ElectroBun</strong>, an Electron alternative that is TypeScript-native. The project forks from <strong>co(lab)</strong>, an existing TypeScript codebase. The desktop shell, renderer integration (ghostty/rio), and UI surface all require deep JavaScript/TypeScript interop at every integration boundary.</p><p>Using Go as the primary language would require FFI bridges for every desktop integration point -- ElectroBun APIs, renderer lifecycle management, IPC with the shell process, DOM/UI event handling, and plugin extensibility. This would add substantial complexity, maintenance burden, and performance overhead with no architectural benefit for a desktop control-plane application.</p><p>The constitution already recognizes TypeScript (TS7 Native) and Bun as valid choices (L19, L21). This ADR formalizes TypeScript + Bun as the <strong>primary</strong> language for heliosApp rather than a secondary fallback.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Use TypeScript with the Bun runtime as the primary language and execution environment for heliosApp. Go, Rust, and Zig remain available for performance-critical subsystems (e.g., terminal multiplexer integration, session checkpoint I/O) where native code provides a measurable benefit, but TypeScript is the default.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>Zero impedance mismatch with ElectroBun&#39;s TypeScript-native APIs</li><li>Direct code reuse from the co(lab) fork base without language translation</li><li>Single runtime (Bun) for build, test, and execution toolchain</li><li>Aligns with constitution&#39;s existing Bun ecosystem preference (L21)</li></ul><p><strong>Negative:</strong></p><ul><li>Diverges from the &quot;Prefer Go&quot; default, which may cause confusion for contributors expecting Go</li><li>TypeScript&#39;s runtime performance ceiling is lower than Go for compute-heavy paths (mitigated by using native code for those specific paths)</li></ul><p><strong>Neutral:</strong></p><ul><li>Testing stack (Vitest + Playwright) is already TypeScript-native per constitution L25</li><li>This decision does not affect other Phenotype repositories; the Go preference remains the default elsewhere</li></ul><h2 id="sunset" tabindex="-1">Sunset <a class="header-anchor" href="#sunset" aria-label="Permalink to &quot;Sunset&quot;">​</a></h2><p>N/A -- This is a permanent architectural decision for the heliosApp repository. The ElectroBun desktop shell is fundamentally TypeScript-native, making this a structural constraint rather than a temporary exception.</p>',19)])])}const g=t(o,[["render",n]]);export{d as __pageData,g as default};
